def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers, otherwise False.
    The number a is less than 100.

    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if a < 2:
        return False

    for i in range(2, 100):
        if not is_prime(i):
            continue
        for j in range(i, 100):
            if not is_prime(j):
                continue
            for k in range(j, 100):
                if not is_prime(k):
                    continue
                if i * j * k == a:
                    return True
    return False

