def encrypt(s):
    """
    Encrypts a given string by rotating the alphabet.
    The rotation is such that each letter is shifted by two multiplied to two places.

    :param s: The input string to be encrypted.
    :return: The encrypted string.
    """
    def rot(n):
        return chr((ord(n) - ord('a') + 4) % 26 + ord('a'))

    return ''.join(rot(c) for c in s)

