def encode(message):
    """
    Encodes a given message by swapping the case of all letters and replacing
    each vowel with the letter that appears 2 places ahead in the English alphabet.

    :param message: The input message to be encoded.
    :return: The encoded message.
    """
    def swap_case_and_shift_vowel(c):
        if c.isalpha():
            if c in 'aeiouAEIOU':
                return chr((ord(c) - ord('a') + 2) % 26 + ord('a')) if c.islower() else chr((ord(c) - ord('A') + 2) % 26 + ord('A'))
            else:
                return c.swapcase()
        return c

    return ''.join(swap_case_and_shift_vowel(c) for c in message)

