def f(n):
    """
    Returns a list of size n where the value of the element at index i is the factorial of i if i is even
    or the sum of numbers from 1 to i otherwise.

    Parameters:
    n (int): The size of the list to be generated.

    Returns:
    list: A list of integers based on the specified conditions.
    """
    def factorial(x):
        """Calculate the factorial of a given number x."""
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(2, x + 1):
            result *= i
        return result

    def sum_to_n(x):
        """Calculate the sum of numbers from 1 to x."""
        return sum(range(1, x + 1))

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_n(i))
    return result

