def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def digit_sum(n):
        """
        Calculate the sum of digits of an integer n.
        If n is negative, the first digit is considered negative.
        """
        if n == 0:
            return 0
        elif n < 0:
            return -int(str(n)[1]) + digit_sum(int(str(n)[2:]))
        else:
            return int(str(n)[0]) + digit_sum(int(str(n)[1:]))

    return sum(1 for num in arr if digit_sum(num) > 0)

def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    words = test.split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    max_count = max(frequency.values())
    result = {word: count for word, count in frequency.items() if count == max_count}

    return result

