def intersection(interval1, interval2):
    """Determine if the length of intersection of two intervals is a prime number."""
    start1, end1 = interval1
    start2, end2 = interval2

    intersection_start = max(start1, start2)
    intersection_end = min(end1, end2)

    intersection_length = intersection_end - intersection_start

    return "YES" if is_prime(intersection_length) else "NO"

def is_nested(string):
    """
    Determines if there is a valid subsequence of brackets where at least one bracket
    in the subsequence is nested.

    :param string: A string consisting only of square brackets.
    :return: True if there is a nested bracket, False otherwise.
    """
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    nested = True

    return nested

