def specialFilter(nums):
    """
    Returns the count of numbers in the list that are greater than 10 and
    both the first and last digits are odd.

    :param nums: List of integers
    :return: Integer count of numbers meeting the criteria
    """
    def is_odd_digit(n):
        return n in {1, 3, 5, 7, 9}

    def first_and_last_digit_odd(n):
        s = str(n)
        return is_odd_digit(int(s[0])) and is_odd_digit(int(s[-1]))

    return sum(1 for num in nums if num > 10 and first_and_last_digit_odd(num))

