def solve(s):
    """
    Reverses the case of each letter in the string s.
    If no letters are present, reverses the entire string.

    :param s: Input string
    :return: Transformed string
    """
    if not any(char.isalpha() for char in s):
        return s[::-1]

    result = []
    for char in s:
        if char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)

    return ''.join(result)

